// 1. accumulate $H = X^\top X$ and $\overline{|x|}$ from calibration
// 2. $h_d \leftarrow \mathrm{diag}(H/N)$;  $\bar x \leftarrow \overline{|x|}/N$
// 3. for $i = 0\ldots N_\alpha{-}1$:  $r = i/N_\alpha$;  $s = \bar x^r$ (range-normalized)
// 4.   $\hat W = \mathrm{quant}(W \mathrm{diag}(s))/\mathrm{diag}(s)$;  $\mathrm{err} = \sum_{ij} h_{d,j}(W - \hat W)^2_{ij}$
// 5.   keep $s^\star$ minimizing err
// 6. $W' \leftarrow W\,\mathrm{diag}(s^\star)$;  $H' \leftarrow \mathrm{diag}(1/s^\star)\,H\,\mathrm{diag}(1/s^\star) + \delta I$
// 7. $H'^{-1} \leftarrow$ Cholesky-inverse$(H')$
// 8. run column-wise GPTQ on $W'$ with $H'^{-1}$ and per-group min-max scales
// 9. return $W^{(q)} \mathrm{diag}(1/s^\star)$

// 1. accumulate $H = X^\top X$;  $H_{damp} \leftarrow H/N + \delta I$;  $H^{-1}_d \leftarrow \mathrm{diag}(\mathrm{Cholesky\_inv}(H_{damp}))$
// 2. $v \leftarrow \sqrt{\mathrm{diag}(H_{damp})}$;  $w_{max} \leftarrow \max_i|W_{i,:}|$
// 3. for $\alpha \in \{0, 0.1, \ldots, 1.2\}$ and use_wmax $\in \{T, F\}$:
// 4.   $S = v^\alpha / w_{max}^{1-\alpha}$ (or $S = v^\alpha$);  normalize mean to 1
// 5.   for clip $\in \{0.8, 0.85, 0.9, 0.95, 1.0\}$:
// 6.     $W_q^{(\alpha,c)} = \mathrm{quant}(W S, \mathrm{scale} = c\,\mathrm{groupmax})/S$
// 7.     $\mathrm{err} = \sum_{ij} (W - W_q^{(\alpha,c)})_{ij}^2 / H^{-1}_{d,j}$
// 8.   keep best $(S^\star, c^\star)$
// 9. run GPTQ column-wise on $W$ in scaled coords using best $(S^\star, c^\star)$ for per-group scales

// 1. accumulate $H_d = \overline{X^2}$ from calibration
// 2. $c \leftarrow (h_d^{1/4})/\overline{h_d^{1/4}}$ clipped to $[0.5, 2]$
// 3. $W_n \leftarrow W/\mathrm{diag}(c)$;  $h_n \leftarrow h_d \odot c^2$
// 4. for each group $g$ of size $G$:
// 5.   if $G > 8$:  clip $\leftarrow$ top-$\lceil \mathrm{ratio}\, G \rceil$ |entry|;  else  clip $\leftarrow$ groupmax
// 6.   $\mathrm{scale}_g \leftarrow$ clip$/q_{max}$;  $W_c \leftarrow \mathrm{clamp}(W_g, \pm$clip$)$;  $Q \leftarrow$ round$\to$int
// 7.   bias $\leftarrow \mathrm{clamp}(\sum_j (W_g - Q)_j h_{n,j} / \sum_j h_{n,j},\ \pm 0.5\,\mathrm{scale})$
// 8.   $Q \leftarrow \mathrm{round}((W_c + \mathrm{bias})/\mathrm{scale}) \cdot \mathrm{scale}$
// 9. return $Q \cdot \mathrm{diag}(c)$

// 1. run vanilla GPTQ with min-max per-group scales -> $Q$
// 2. compute $\bar a_c = \overline{|x_c|}$ per input channel
// 3. for each group $g$:
// 4.   $s_0 \leftarrow \max_{j\in g} |W_{:,j}| / q_{max}$
// 5.   for $\mu \in$ linspace$(0.88, 1.12, 20)$:
// 6.     $Q' \leftarrow$ round$(W_g/(\mu s_0)) \cdot (\mu s_0)$
// 7.     err $\leftarrow \sum_{ij}(W_g - Q')_{ij}^2\, \bar a_{g,j}$
// 8.   keep $\mu^\star$ minimizing err;  overwrite $Q_g$ with the corresponding quantization
// 9. return $Q$

